{"cards": [{"node_code": "N_06509188a6085ca7", "definition": "研究土木工程施工过程中对大气、水体、土壤及声环境等外部介质的污染控制与监测技术，旨在减少施工活动对周边生态环境的负面影响。", "boundary": "本节点聚焦于施工产生的污染物（扬尘、噪声、废水、固废）的源头控制、过程处理及末端治理。边界涵盖环境监测指标、排放标准及具体治理工艺（如沉淀池、隔音屏障）。不包含施工现场内部的人员安全防护、机械设备操作规范或具体的结构材料施工工艺参数。", "includes": ["施工扬尘、噪声、废水及固体废弃物的控制与处理技术", "施工现场环境监测、污染物排放达标管理及生态修复措施"], "excludes": ["施工人身安全防护、机械设备安全操作等安全技术（归入施工安全技术与作业防护）", "具体结构材料的制备工艺或施工技术参数（归入具体结构施工节点）"], "sibling_distinctions": [{"other_code": "N_94d09d1154b6ec46", "rule": "本节点关注对“自然环境介质”（空气、水、土、声）的物理/化学污染控制；兄弟节点关注“现场秩序、人员行为及视觉形象”的管理。"}, {"other_code": "N_34451d92a13ad9ab", "rule": "本节点关注具体的“污染物治理技术”与监测；兄弟节点关注“资源节约、循环利用及绿色建造理念”的系统性应用。"}], "cross_boundary_rule": "若措施旨在降低特定污染物排放（如洒水降尘），归入本节点；若措施旨在优化资源使用效率（如雨水收集利用），归入绿色施工。"}, {"node_code": "N_94d09d1154b6ec46", "definition": "研究土木工程施工现场的标准化作业、人员行为规范、现场视觉形象及社区关系协调，旨在提升施工管理的规范化水平与社会接受度。", "boundary": "本节点聚焦于施工现场的“软环境”与“秩序管理”，包括围挡设置、标识标牌、材料堆放、人员着装及文明施工标准。边界涵盖现场整洁度、噪音扰民的社会协调及施工形象展示。不包含具体的环境污染治理技术（如废水处理工艺）或资源节约技术。", "includes": ["施工现场围挡、标识标牌、材料堆放及现场整洁度管理", "施工人员行为规范、着装要求及社区关系协调与投诉处理"], "excludes": ["施工扬尘、噪声、废水等具体污染物的物理/化学治理技术（归入环境控制）", "绿色施工中的资源节约、循环利用及低碳建造技术（归入绿色施工）"], "sibling_distinctions": [{"other_code": "N_06509188a6085ca7", "rule": "本节点关注“现场秩序、人员行为及视觉形象”；兄弟节点关注“自然环境介质”的污染控制与治理。"}, {"other_code": "N_34451d92a13ad9ab", "rule": "本节点关注“管理标准与行为规范”；兄弟节点关注“技术措施与资源效率”。"}], "cross_boundary_rule": "若内容涉及现场整洁、标识、人员管理等非技术性规范，归入本节点；若涉及具体的环保技术或资源节约手段，归入环境控制或绿色施工。"}, {"node_code": "N_34451d92a13ad9ab", "definition": "研究土木工程施工中资源节约、循环利用、低碳建造及绿色建造技术的系统性应用，旨在提升工程全生命周期的资源效率与环境可持续性。", "boundary": "本节点聚焦于施工过程中的“资源效率”与“绿色技术”，包括节能节水、材料循环利用、装配式建造及低碳工艺。边界涵盖绿色施工评价体系、资源优化配置及新型环保材料的应用。不包含具体的污染物末端治理技术（如废水沉淀）或现场秩序管理。", "includes": ["施工节能、节水、节材及材料循环利用技术", "绿色建造工艺、装配式施工及低碳施工技术应用"], "excludes": ["施工扬尘、噪声、废水等具体污染物的末端治理技术（归入环境控制）", "施工现场围挡、标识、人员行为等现场秩序管理（归入文明施工）"], "sibling_distinctions": [{"other_code": "N_06509188a6085ca7", "rule": "本节点关注“资源节约与循环利用”（源头减量）；兄弟节点关注“污染物治理与监测”（末端控制）。"}, {"other_code": "N_94d09d1154b6ec46", "rule": "本节点关注“技术措施与资源效率”；兄弟节点关注“管理标准与行为规范”。"}], "cross_boundary_rule": "若措施旨在提高资源使用效率或减少资源消耗（如雨水收集、废料再生），归入本节点；若措施旨在处理已产生的污染物（如废水净化），归入环境控制。"}]}
